import json
import sys


def extract_fields(data):
    """Extract exact, case-sensitive labels from label: value lines."""
    invalid = {"error": "invalid_input"}
    if not isinstance(data, dict) or set(data) != {"text", "fields"}:
        return invalid
    text, fields = data["text"], data["fields"]
    if not isinstance(text, str) or len(text) > 100000:
        return invalid
    if not isinstance(fields, list) or not 1 <= len(fields) <= 100:
        return invalid
    if any(not isinstance(field, str) for field in fields):
        return invalid
    requested = set(fields)
    if len(requested) != len(fields):
        return invalid

    found = {}
    for line in text.splitlines():
        label, separator, value = line.partition(":")
        if not separator or label not in requested:
            continue
        if label in found:
            return invalid
        found[label] = value.strip()
    return {"fields": {label: found[label] for label in fields if label in found}}


def main():
    try:
        data = json.load(sys.stdin)
    except (ValueError, UnicodeError):
        result = {"error": "invalid_input"}
    else:
        result = extract_fields(data)
    json.dump(result, sys.stdout, ensure_ascii=True)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
